// src/sw.js
var APP_VERSION = "7e46dab9feee";
var swUrl = new URL(self.location.href);
var BASE = swUrl.pathname.slice(0, swUrl.pathname.lastIndexOf("/") + 1);
var PREFIX = BASE.replace(/\/$/, "");
var TYPES = {
  html: "text/html; charset=utf-8",
  css: "text/css; charset=utf-8",
  js: "application/javascript",
  mjs: "application/javascript",
  json: "application/json",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  webp: "image/webp",
  avif: "image/avif",
  svg: "image/svg+xml",
  gif: "image/gif",
  ico: "image/x-icon",
  woff2: "font/woff2",
  woff: "font/woff",
  ttf: "font/ttf",
  otf: "font/otf",
  txt: "text/plain; charset=utf-8",
  xml: "application/xml",
  webmanifest: "application/manifest+json",
  map: "application/json",
  md: "text/plain; charset=utf-8"
};
var PHP_INI = `
session.save_path=/persist/sessions
session.use_strict_mode=0
session.use_cookies=1
session.use_only_cookies=1
session.cookie_httponly=1
session.cookie_samesite=Lax
session.gc_maxlifetime=28800
display_errors=0
log_errors=1
expose_php=0
upload_tmp_dir=/persist/tmp
post_max_size=16M
upload_max_filesize=16M
date.timezone=Europe/Kyiv
`;
var php = new PhpCgiWorker({
  prefix: BASE,
  docroot: "/persist/www",
  exclude: [PREFIX + "/seed"],
  rewrite: (pathname) => {
    if (pathname === PREFIX || pathname === PREFIX + "/") {
      return { path: "/login.html" };
    }
    return void 0;
  },
  types: TYPES,
  ini: PHP_INI,
  sharedLibs: [php_wasm_sqlite_default, php_wasm_mbstring_default, php_wasm_iconv_default, php_wasm_zlib_default, php_wasm_openssl_default],
  onRequest: () => {
  }
});
var DOCROOT = "/persist/www";
async function seed() {
  const inst = await php.binary;
  const FS2 = inst.FS;
  const step = async (name2, fn) => {
    try {
      return await fn();
    } catch (e) {
      const m = e && e.message ? e.message : JSON.stringify(e);
      console.error('[seed] step "' + name2 + '" failed:', m);
      throw e;
    }
  };
  const ensureDir = (path) => {
    if (!FS2.analyzePath(path).exists) {
      FS2.mkdir(path, 509);
    }
  };
  const ensureParent = (path) => {
    const idx = path.lastIndexOf("/");
    if (idx > 0) {
      ensureDir(path.slice(0, idx));
    }
  };
  await step("dirs", () => {
    ["/persist", "/persist/www", "/persist/www/api", "/persist/www/api/data", "/persist/www/data", "/persist/sessions", "/persist/tmp"].forEach(ensureDir);
  });
  const marker = DOCROOT + "/.app-version";
  const current = FS2.analyzePath(marker).exists ? FS2.readFile(marker, { encoding: "utf8" }) : "";
  const dirty = current !== APP_VERSION;
  const manifest = await step("manifest", async () => {
    const res = await fetch(new URL("manifest.json", swUrl.href));
    if (!res.ok) throw new Error("manifest status " + res.status);
    return res.json();
  });
  const files = manifest.files || [];
  await navigator.locks.request("php-wasm-fs-lock", async () => {
    for (const entry of files) {
      const dest = DOCROOT + "/" + entry.path;
      if (!dirty && FS2.analyzePath(dest).exists) {
        continue;
      }
      if (/^api\/data\//.test(entry.path) && FS2.analyzePath(dest).exists) {
        continue;
      }
      await step("write " + entry.path, async () => {
        const res = await fetch(new URL("seed/" + entry.path, swUrl.href));
        if (!res.ok) {
          throw new Error("seed fetch failed: " + entry.path + " (" + res.status + ")");
        }
        const buf = new Uint8Array(await res.arrayBuffer());
        ensureParent(dest);
        FS2.writeFile(dest, buf);
      });
    }
    FS2.writeFile(marker, APP_VERSION, { encoding: "utf8" });
    await step("syncfs", () => new Promise((resolve, reject) => {
      FS2.syncfs(false, (err2) => err2 ? reject(err2) : resolve());
    }));
  });
}
self.addEventListener("install", (event2) => {
  console.log("[forno] install, version", APP_VERSION);
  event2.waitUntil(php.handleInstallEvent(event2));
});
self.addEventListener("activate", (event2) => {
  console.log("[forno] activate");
  event2.waitUntil((async () => {
    try {
      await clients.claim();
      await php.binary;
      await seed();
      const clientList = await clients.matchAll({ type: "window" });
      clientList.forEach((client) => client.postMessage({ type: "forno-ready", version: APP_VERSION }));
    } catch (err2) {
      console.error("[forno] activate failed:", err2 && err2.message ? err2.message : err2);
      try {
        const clientList = await clients.matchAll({ type: "window" });
        clientList.forEach((client) => client.postMessage({
          type: "forno-error",
          error: err2 && err2.message ? err2.message : String(err2)
        }));
      } catch (e) {
      }
      throw err2;
    }
  })());
});
self.addEventListener("fetch", (event2) => {
  try {
    php.handleFetchEvent(event2);
  } catch (e) {
    console.error("[fetch] handler error:", e && e.message ? e.message : String(e));
  }
});
self.addEventListener("message", (event2) => {
  php.handleMessageEvent(event2);
});
